const GAME_INFO={cover:{label:'표지 조각',emoji:'🧩'},initials:{label:'초성 퀴즈',emoji:'🔤'},couples:{label:'주인공 짝 잇기',emoji:'💘'},excerpt:{label:'발췌 퀴즈',emoji:'📖'},dialogue:{label:'대사 주인 찾기',emoji:'💬'},puzzle:{label:'슬라이딩 퍼즐',emoji:'🧠'},mix:{label:'랜덤게임',emoji:'🎲'}};
const STORE='dmnovel_minigame_v1_';
const GAME_PROFILE_KEY='dm_game_profile_v1';
const GAME_TYPES=['cover','initials','couples','excerpt','dialogue','puzzle','mix'];
function defaultGameStats(){return {cover:{correct:0,score:0,clears:0,level:1},initials:{correct:0,score:0,clears:0,level:1},couples:{correct:0,score:0,clears:0,level:1},excerpt:{correct:0,score:0,clears:0,level:1},dialogue:{correct:0,score:0,clears:0,level:1},puzzle:{correct:0,score:0,clears:0,level:1,bestSize:5},mix:{correct:0,score:0,clears:0,level:1}}}
function defaultGameProfile(){return {name:'',totalCorrect:0,totalScore:0,games:defaultGameStats(),savedAt:''}}
function mergeProfile(src){const base=defaultGameProfile();if(!src||typeof src!=='object')return base;base.name=String(src.name||'').replace(/\s+/g,'').slice(0,6);base.totalCorrect=Number(src.totalCorrect)||0;base.totalScore=Number(src.totalScore)||0;base.savedAt=String(src.savedAt||'');GAME_TYPES.forEach(k=>{const s=src.games&&src.games[k]||{};base.games[k]={...base.games[k],...Object.fromEntries(Object.entries(s).filter(([kk,v])=>['correct','score','clears','level','bestSize'].includes(kk) && Number.isFinite(Number(v))).map(([kk,v])=>[kk,Number(v)]))};});return base}
function loadGameProfile(){try{return mergeProfile(JSON.parse(localStorage.getItem(GAME_PROFILE_KEY)||'null'))}catch(e){return defaultGameProfile()}}
let gameProfile=loadGameProfile();
function saveGameProfile(notify=false){gameProfile.savedAt=new Date().toISOString();try{localStorage.setItem(GAME_PROFILE_KEY,JSON.stringify(gameProfile));if(notify)alert('게임 정보가 저장되었습니다. 이 데이터는 마스터페이지 설정백업에 함께 포함됩니다.')}catch(e){if(notify)alert('게임 정보를 저장하지 못했습니다.')}}
function sanitizeName(v){return String(v||'').replace(/\s+/g,'').slice(0,6)}
function usernameLabel(){return sanitizeName(gameProfile.name)||'PLAYER'}
function ensureGameStat(type){if(!gameProfile.games||typeof gameProfile.games!=='object')gameProfile.games=defaultGameStats();if(!gameProfile.games[type])gameProfile.games[type]=defaultGameStats()[type]||{correct:0,score:0,clears:0,level:1};return gameProfile.games[type]}
function computeLevel(type,stat){if(type==='puzzle'){const best=Math.max(5,Number(stat.bestSize)||5);return Math.max(1,Math.min(99,Math.round(best/5)))}if(type==='couples')return Math.max(1,1+Math.floor((stat.clears||0)/2)+Math.floor((stat.correct||0)/10));if(type==='mix')return Math.max(1,1+Math.floor((stat.correct||0)/8)+Math.floor((stat.clears||0)/2));return Math.max(1,1+Math.floor((stat.correct||0)/5)+Math.floor((stat.clears||0)/2))}
function refreshLevels(type){const stat=ensureGameStat(type);stat.level=computeLevel(type,stat)}
function recordCorrect(type,score=10,count=1){const stat=ensureGameStat(type);stat.correct+=(count||1);stat.score+=(score||0);gameProfile.totalCorrect+=(count||1);gameProfile.totalScore+=(score||0);refreshLevels(type)}
function recordClear(type,bonus=20){const stat=ensureGameStat(type);stat.clears+=1;stat.score+=(bonus||0);gameProfile.totalScore+=(bonus||0);refreshLevels(type)}
function updatePuzzleBest(size){const stat=ensureGameStat('puzzle');const n=Number(size)||5;stat.bestSize=Math.max(Number(stat.bestSize)||5,n);refreshLevels('puzzle')}
function statsMarkup(){return GAME_TYPES.map(type=>{const stat=ensureGameStat(type),label=GAME_INFO[type].label;const extra=type==='puzzle'?`<span>최고 퍼즐 ${Math.max(5,Number(stat.bestSize)||5)}×${Math.max(5,Number(stat.bestSize)||5)}</span>`:'';return `<li><div><strong>${esc(label)}</strong><span>정답 ${stat.correct} · 클리어 ${stat.clears}</span>${extra}</div><em>LV ${stat.level}</em></li>`}).join('')}
function ensureProfileModal(){if(document.getElementById('gameProfileBackdrop'))return;document.body.insertAdjacentHTML('beforeend',`<div id="gameProfileBackdrop" class="game-profile-backdrop" aria-hidden="true"><section class="game-profile-modal" role="dialog" aria-modal="true" aria-labelledby="gameProfileTitle"><div class="game-profile-head"><h2 id="gameProfileTitle">PLAYER DATA</h2><button type="button" id="gameProfileClose" class="profile-close" aria-label="닫기">×</button></div><p class="game-profile-desc">아이디와 점수는 현재 기기에 저장됩니다. SAVE를 누르면 마스터페이지 설정백업에 함께 포함됩니다.</p><label class="game-profile-label" for="gameProfileName">아이디 (최대 6글자)</label><div class="game-profile-name-row"><input id="gameProfileName" type="text" maxlength="6" autocomplete="off" placeholder="아이디 입력"><button type="button" id="gameProfileApply" class="outline">적용</button></div><div class="game-profile-summary"><div><span>TOTAL SCORE</span><strong id="gameProfileScore">0</strong></div><div><span>CORRECT</span><strong id="gameProfileCorrect">0</strong></div></div><ul id="gameProfileStats" class="game-profile-stats"></ul><div class="game-profile-actions"><button type="button" id="gameProfileSave" class="primary">SAVE</button><button type="button" id="gameProfileCloseBtn" class="outline">닫기</button></div></section></div>`);document.getElementById('gameProfileClose').addEventListener('click',()=>closeProfileModal());document.getElementById('gameProfileCloseBtn').addEventListener('click',()=>closeProfileModal());document.getElementById('gameProfileBackdrop').addEventListener('click',e=>{if(e.target.id==='gameProfileBackdrop'&&!document.getElementById('gameProfileBackdrop').dataset.force)closeProfileModal()});document.getElementById('gameProfileApply').addEventListener('click',()=>{const inp=document.getElementById('gameProfileName');const name=sanitizeName(inp.value);if(!name){alert('아이디를 입력해 주세요.');inp.focus();return}gameProfile.name=name;updateProfileButton();renderProfileSnapshot();});document.getElementById('gameProfileSave').addEventListener('click',()=>{const inp=document.getElementById('gameProfileName');const name=sanitizeName(inp.value);if(!name){alert('아이디를 입력해 주세요.');inp.focus();return}gameProfile.name=name;saveGameProfile(true);renderProfileSnapshot();updateProfileButton();closeProfileModal()});document.getElementById('gameProfileName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.getElementById('gameProfileApply').click()}})}
function renderProfileSnapshot(){ensureProfileModal();document.getElementById('gameProfileName').value=usernameLabel()==='PLAYER'?'':usernameLabel();document.getElementById('gameProfileScore').textContent=String(gameProfile.totalScore||0);document.getElementById('gameProfileCorrect').textContent=String(gameProfile.totalCorrect||0);document.getElementById('gameProfileStats').innerHTML=statsMarkup()}
function openProfileModal(force=false){ensureProfileModal();renderProfileSnapshot();const b=document.getElementById('gameProfileBackdrop');b.classList.add('open');b.setAttribute('aria-hidden','false');b.dataset.force=force?'1':'';document.body.classList.add('modal-open');document.getElementById('gameProfileClose').hidden=!!force;document.getElementById('gameProfileCloseBtn').hidden=!!force;setTimeout(()=>document.getElementById('gameProfileName').focus(),0)}
function closeProfileModal(){const b=document.getElementById('gameProfileBackdrop');if(!b)return;if(b.dataset.force){if(!sanitizeName(document.getElementById('gameProfileName')?.value||gameProfile.name)){alert('아이디를 먼저 저장해 주세요.');return}b.dataset.force=''}b.classList.remove('open');b.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function updateProfileButton(){document.querySelectorAll('.user-btn').forEach(btn=>btn.textContent=usernameLabel())}
const app=document.getElementById('app');let current=null;let active=null;let locked=false;let feedback='';let flash=false;let puzzleLevel=1;let puzzleCount=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffled=a=>{const b=a.slice();for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const sample=a=>shuffled(a).slice(0,Math.min(10,a.length));
const normal=s=>String(s||'').normalize('NFKC').toLocaleLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');
function save(key,data){try{localStorage.setItem(STORE+key,JSON.stringify(data))}catch(e){}}
function load(key){try{return JSON.parse(localStorage.getItem(STORE+key))}catch(e){return null}}
function clear(key){try{localStorage.removeItem(STORE+key)}catch(e){}}
