function home(){puzzleChosen=false;puzzleAnimating=false;clearQuizAdvance();current=null;active=null;try{history.replaceState(null,'',location.pathname)}catch(e){};app.innerHTML=renderGameHeader('CASINO-JEONG🎰',true)+`<p class="intro">원하는 게임을 선택해 주세요.</p><button class="feature" data-game="mix"><strong>🎲 랜덤게임</strong><span>등록된 문제 중 10문제 랜덤 출제</span></button><section class="cards">${['cover','initials','couples','excerpt','dialogue','puzzle'].map(k=>`<button class="game-card" data-game="${k}"><span class="emoji">${GAME_INFO[k].emoji}</span><strong>${GAME_INFO[k].label}</strong></button>`).join('')}</section>`;app.querySelectorAll('[data-game]').forEach(el=>el.addEventListener('click',()=>start(el.dataset.game)));bindHeaderUI()}
function start(game,reset=false){current=game;locked=false;feedback='';flash=false;if(game==='puzzle'){puzzleLevel=1;puzzleCount=0;newPuzzle();return}if(game==='couples'){newCouples();return}if(game==='mix'){newMix();return}if(!reset){
  const saved=load(game);
  if(saved?.type===game&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<=GAME_DATA[game].length&&Array.isArray(saved.order)){
    const count=GAME_DATA[game].length;
    const valid=saved.order.filter((n,i,a)=>Number.isInteger(n)&&n>=0&&n<count&&a.indexOf(n)===i);
    const added=shuffled(GAME_DATA[game].map((_,i)=>i).filter(i=>!valid.includes(i)));
    active={type:game,index:Math.min(saved.index,valid.length),order:valid.concat(added)};
    save(game,active);renderQuiz();return;
  }
}
active={type:game,index:0,order:shuffled(GAME_DATA[game].map((_,i)=>i))};save(game,active);renderQuiz()}

let quizAdvanceTimer=null;let puzzleChosen=false;let puzzleAnimating=false;let puzzleInvalidTimer=null;
function clearQuizAdvance(){if(quizAdvanceTimer!==null){clearTimeout(quizAdvanceTimer);quizAdvanceTimer=null}}
function advanceAfterThreeSeconds(fn){clearQuizAdvance();quizAdvanceTimer=setTimeout(()=>{quizAdvanceTimer=null;fn()},3000)}
function base(title,body){clearQuizAdvance();app.innerHTML=renderGameHeader(title,true)+body;bindBack();bindHeaderUI()}
const HANGUL_INITIALS='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';
function initialLetter(ch){const cp=ch.codePointAt(0);return cp>=44032&&cp<=55203?HANGUL_INITIALS[Math.floor((cp-44032)/588)]:ch}
function initialMarkup(item,showHint=false){
  const title=item.answer;
  const cell=ch=>`<span class="initial">${esc(initialLetter(ch))}</span>`;
  if(!showHint)return [...title].filter(ch=>!/[\s\p{P}\p{S}]/u.test(ch)).map(cell).join('');
  return title.match(/\s+|[^\s]+/gu).map(part=>{
    if(/^\s+$/u.test(part))return '';
    const bits=[...part].map(ch=>/[\p{P}\p{S}]/u.test(ch)?`<span class="initial-punct">${esc(ch)}</span>`:cell(ch)).join('');
    return `<span class="initial-word">${bits}</span>`;
  }).join('');
}
function hintMarkup(item){return `<div class="initial-help"><button type="button" class="outline" id="space-hint">💡 띄어쓰기 힌트</button><small>정답 입력 시 띄어쓰기·기호는 생략해도 됩니다.</small></div>`}
function bindInitialHint(item){const btn=document.getElementById('space-hint');if(!btn)return;btn.addEventListener('click',()=>{const el=document.getElementById('initials');if(!el||el.classList.contains('hinted'))return;el.classList.add('hinted');el.innerHTML=initialMarkup(item,true);btn.disabled=true;btn.textContent='띄어쓰기·기호 힌트 사용됨';});}
function quizText(type,item){if(type==='initials')return `<p class="question">아래 초성에 해당하는 작품의 제목은?</p><div class="initials" id="initials">${initialMarkup(item)}</div>${hintMarkup(item)}`;if(type==='cover')return `<p class="question">아래 표지 조각의 작품 제목은?</p><div class="prompt image-crop">${item.image?`<img src="${esc(item.image)}" alt="표지 조각">`:`<span class="image-placeholder">${esc(item.text)}</span>`}</div>`;if(type==='dialogue')return `<p class="question">아래 대사의 주인공 이름은?</p><div class="prompt bubble">${esc(item.text)}</div>`;return `<p class="question">아래 발췌가 나오는 작품의 제목은?</p>${item.image?`<div class="prompt excerpt-picture"><img src="${esc(item.image)}" alt="발췌 이미지"></div>`:`<div class="prompt excerpt">${esc(item.text)}</div>`}`}

function getQuestion(type,index){return GAME_DATA[type]?.[index]}
function renderQuiz(){const {type,index}=active;const arr=GAME_DATA[type];if(index>=arr.length){complete(type,arr.length);return}const item=arr[active.order[index]];locked=false;feedback='';base(GAME_INFO[type].label,`<section class="panel"><div class="question-head"><strong>${GAME_INFO[type].emoji} ${GAME_INFO[type].label}</strong><span class="counter">${index+1} / ${arr.length}</span></div>${item.demo?'<p class="sample">※ 아직 실제 문제 데이터가 없는 예시 문항입니다.</p>':''}${quizText(type,item).replace('</p>','</p><p id="feedback" class="feedback" role="status" aria-live="polite"></p>')}<form id="answer-form"><input id="answer" type="text" placeholder="${type==='dialogue'?'주인공 이름':'작품 제목'} 입력" autocomplete="off" aria-label="정답 입력" required><div class="actions"><button class="primary" type="submit" id="submit">제출</button></div></form><div class="actions" id="next-area" hidden><button id="next" class="primary next-btn">다음 문제 →</button></div></section>${footer(type)}`);document.getElementById('answer-form').addEventListener('submit',e=>{e.preventDefault();const inp=document.getElementById('answer');const answer=normal(inp.value);const accepted=(item.answers||[item.answer]).some(x=>normal(x)===answer);let stat=document.getElementById('feedback');stat.className='feedback '+(accepted?'good':'bad');stat.textContent=accepted?'정답입니다!':'틀렸습니다.';if(accepted){recordCorrect(type,10);locked=true;document.getElementById('answer').disabled=true;document.getElementById('submit').disabled=true;document.querySelectorAll('.initial').forEach(e=>e.classList.add('good'));save(type,{...active,index:index+1});advanceAfterThreeSeconds(()=>{if(current!==type||!active||active.index!==index)return;active.index++;renderQuiz()})}else{const initials=document.querySelectorAll('.initial');initials.forEach(e=>{e.classList.remove('bad');void e.offsetWidth;e.classList.add('bad')});inp.select()}});if(type==='initials')bindInitialHint(item);bindRestart(type)}
function footer(type){return `<div class="footer-actions"><button class="outline" id="restart">처음부터 다시풀기</button><button class="outline" id="menu">게임 목록으로</button></div>`}
