function complete(type,count){recordClear(type,20);base(GAME_INFO[type].label,`<section class="panel done"><div class="emoji">🎉</div><h2>모두 맞혔습니다!</h2><p>${count}문제를 완료했습니다.</p><button class="primary" id="again">처음부터 다시풀기</button></section><div class="footer-actions"><button class="outline" id="menu">게임 목록으로</button></div>`);document.getElementById('again').onclick=()=>{clear(type);start(type,true)};document.getElementById('menu').onclick=home}
// 짝 잇기: 최대 10커플 무작위 추첨, 양쪽 방향도 무작위, 저장 없음
let pairState=null;
function newCouples(){current='couples';const chosen=sample(GAME_DATA.couples);pairState={left:[],right:[],connected:[],selected:null};const oriented=chosen.map((x,i)=>{const flip=Math.random()<0.5;return {id:i,left:flip?x.b:x.a,right:flip?x.a:x.b}});pairState.left=shuffled(oriented.map(x=>({id:x.id,name:x.left})));pairState.right=shuffled(oriented.map(x=>({id:x.id,name:x.right})));renderCouples()}
function coupleAnswerMarkup(s){return `<section class="pair-answer-guide"><h3>정답 안내</h3><ul>${s.left.map(leftItem=>{const rightItem=s.right.find(x=>x.id===leftItem.id);return `<li><span>${esc(leftItem.name)}</span><em>↔</em><span>${esc(rightItem?.name||'')}</span></li>`}).join('')}</ul></section>`}
function renderCouples(){const s=pairState;const total=s.left.length;base('주인공 짝 잇기',`<section class="panel"><div class="question-head"><strong>💘 주인공 짝 잇기</strong><span class="counter" id="pair-count">${s.connected.length} / ${total}</span></div><p class="pair-note">왼쪽 이름을 누른 뒤 오른쪽에서 짝을 선택하세요. 양쪽 이름은 무작위로 배치됩니다.</p><div class="pair-area"><svg class="connections" id="lines" aria-hidden="true"></svg><div class="pair-board"><div class="pair-col" id="left-col">${s.left.map((x,i)=>`<button class="pair" data-side="left" data-index="${i}">${esc(x.name)}</button>`).join('')}</div><div class="pair-col" id="right-col">${s.right.map((x,i)=>`<button class="pair" data-side="right" data-index="${i}">${esc(x.name)}</button>`).join('')}</div></div></div><p id="feedback" class="feedback" role="status" aria-live="polite"></p><div id="pair-answer-guide" hidden></div><div class="actions" id="pair-next" hidden><button class="primary" id="again">새로운 커플 풀기</button></div></section>${footer('couples')}`);app.querySelectorAll('.pair').forEach(el=>el.addEventListener('click',()=>{const i=+el.dataset.index;if(el.dataset.side==='left'){const id=s.left[i].id;if(s.connected.includes(id))return;s.selected=i;document.querySelectorAll('[data-side="left"]').forEach((b,j)=>b.classList.toggle('selected',j===i));return}if(s.selected===null)return;const id=s.left[s.selected].id;if(s.connected.includes(s.right[i].id))return;const f=document.getElementById('feedback');if(id===s.right[i].id){recordCorrect('couples',5);s.connected.push(id);s.selected=null;f.textContent='정답입니다!';f.className='feedback good';updatePairs();if(s.connected.length===total){recordClear('couples',20);f.textContent='모두 맞혔습니다!';document.getElementById('pair-next').hidden=false;const guide=document.getElementById('pair-answer-guide');if(guide){guide.hidden=false;guide.innerHTML=coupleAnswerMarkup(s);}}}else{f.textContent='틀렸습니다.';f.className='feedback bad'}}));document.getElementById('again').onclick=newCouples;bindRestart('couples',newCouples);updatePairs()}
function updatePairs(){const s=pairState;document.getElementById('pair-count').textContent=`${s.connected.length} / ${s.left.length}`;const left=[...document.querySelectorAll('[data-side="left"]')],right=[...document.querySelectorAll('[data-side="right"]')];left.forEach((b,i)=>{b.classList.toggle('linked',s.connected.includes(s.left[i].id));b.classList.toggle('selected',s.selected===i)});right.forEach((b,i)=>b.classList.toggle('linked',s.connected.includes(s.right[i].id)));const svg=document.getElementById('lines'),area=document.querySelector('.pair-area');const r=area.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${r.width} ${r.height}`);svg.innerHTML=s.connected.map(id=>{const l=left[s.left.findIndex(x=>x.id===id)].getBoundingClientRect(),rr=right[s.right.findIndex(x=>x.id===id)].getBoundingClientRect();const x1=l.right-r.left,y1=l.top-r.top+l.height/2,x2=rr.left-r.left,y2=rr.top-r.top+rr.height/2;return `<path d="M${x1},${y1} C${x1+25},${y1} ${x2-25},${y2} ${x2},${y2}" fill="none" stroke="#379b79" stroke-width="3" stroke-linecap="round"/>`}).join('')}
window.addEventListener('keydown',onIntroKeydown);
window.addEventListener('resize',()=>{if(current==='couples'&&pairState&&document.getElementById('lines'))updatePairs()});
// 랜덤 믹스: 등록된 개별 게임 문항에서 한 문제 단위로 추출, 총 10문제, 저장 없음.
let mixState=null;
function mixPool(){const pool=[];for(const key of ['initials','cover','excerpt','dialogue'])GAME_DATA[key].forEach((item,index)=>pool.push({type:key,index}));GAME_DATA.couples.forEach((item,index)=>pool.push({type:'pair-single',index}));GAME_DATA.puzzle.forEach((item,index)=>pool.push({type:'puzzle-single',index}));return pool}
function newMix(){clearQuizAdvance();current='mix';mixState={questions:sample(mixPool()),index:0};renderMix()}
function renderMix(){clearQuizAdvance();const s=mixState;if(s.index>=s.questions.length){base('랜덤게임',`<section class="panel done"><div class="emoji">🎉</div><h2>10문제 완료!</h2><button class="primary" id="again">다시 풀기</button></section>${footer('mix')}`);document.getElementById('again').onclick=newMix;bindRestart('mix',newMix);return}const q=s.questions[s.index];const item=q.type==='pair-single'?GAME_DATA.couples[q.index]:q.type==='puzzle-single'?GAME_DATA.puzzle[q.index]:GAME_DATA[q.type][q.index];const label=q.type==='pair-single'?'주인공 짝 잇기':q.type==='puzzle-single'?'슬라이딩 퍼즐':GAME_INFO[q.type].label;
if(q.type==='pair-single'){const options=shuffled([item.b,...shuffled(GAME_DATA.couples.filter(x=>x.b!==item.b)).slice(0,3).map(x=>x.b)]);base('🎲 랜덤게임',`<section class="panel"><div class="question-head"><strong>${label}</strong><span class="counter">${s.index+1} / ${s.questions.length}</span></div><p class="question">${esc(item.a)}의 짝은 누구일까요?</p><div class="cards">${options.map((name,i)=>`<button class="outline" data-opt="${i}">${esc(name)}</button>`).join('')}</div><p id="feedback" class="feedback" role="status" aria-live="polite"></p><div class="actions" id="next-area" hidden><button class="primary" id="next">다음 문제 →</button></div></section>${footer('mix')}`);document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{const correct=options[+b.dataset.opt]===item.b;const f=document.getElementById('feedback');f.className='feedback '+(correct?'good':'bad');f.textContent=correct?'정답입니다!':'틀렸습니다.';if(correct){recordCorrect('mix',10);document.querySelectorAll('[data-opt]').forEach(x=>x.disabled=true);const oldIndex=s.index;advanceAfterThreeSeconds(()=>{if(current==='mix'&&mixState===s&&s.index===oldIndex){s.index++;renderMix()}})}});document.getElementById('next').onclick=()=>{s.index++;renderMix()};bindRestart('mix',newMix);return}
if(q.type==='puzzle-single'){startMixPuzzle(item.answer);return}
const questionIndex=s.index;base('🎲 랜덤게임',`<section class="panel"><div class="question-head"><strong>${GAME_INFO[q.type].emoji} ${label}</strong><span class="counter">${s.index+1} / ${s.questions.length}</span></div>${item.demo?'<p class="sample">※ 예시 문제입니다.</p>':''}${quizText(q.type,item)}<form id="answer-form"><input type="text" id="answer" placeholder="정답 입력" required autocomplete="off" aria-label="정답 입력"><div class="actions"><button class="primary" id="submit">제출</button></div></form><p id="feedback" class="feedback" role="status" aria-live="polite"></p><div class="actions" id="next-area" hidden><button class="primary" id="next">다음 문제 →</button></div></section>${footer('mix')}`);document.getElementById('answer-form').onsubmit=e=>{e.preventDefault();const ok=(item.answers||[item.answer]).some(x=>normal(x)===normal(document.getElementById('answer').value));const f=document.getElementById('feedback');f.className='feedback '+(ok?'good':'bad');f.textContent=ok?'정답입니다!':'틀렸습니다.';if(ok){recordCorrect('mix',10);document.getElementById('submit').disabled=true;document.getElementById('answer').disabled=true;document.querySelectorAll('.initial').forEach(x=>x.classList.add('good'));advanceAfterThreeSeconds(()=>{if(current!=='mix'||mixState!==s||s.index!==questionIndex)return;s.index++;renderMix()})}else{document.querySelectorAll('.initial').forEach(x=>{x.classList.remove('bad');void x.offsetWidth;x.classList.add('bad')})}};if(q.type==='initials')bindInitialHint(item);bindRestart('mix',newMix)}
// 제목은 실제 마스터의 출현연월 데이터가 있을 때만 출제합니다.
// 권장 자료 형식: [{"title":"작품 제목", "appearances":["202512","202605"]}, ...]
// 202512 마스터 제목 데이터: AES-256-GCM 암호화, 복호화는 게임 전용 메모리에서만 수행합니다.
const PUZZLE_CIPHER="";
const PUZZLE_NONCE="xFFVYbmOorQu+StF";
const PUZZLE_KEY="R9EGMLhxzQlPehFi1AF0JOm2cGQQl4IRtJB5Zgukv3E=";
let puzzleSource=[];
let puzzleDataPromise=null;
const puzzleBytes=b64=>Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
async function ensurePuzzleData(){
 if(puzzleSource.length)return;
 if(!puzzleDataPromise)puzzleDataPromise=(async()=>{
  if(!crypto?.subtle)throw Error('보안 복호화 기능을 사용할 수 없습니다. HTTPS 환경에서 실행해 주세요.');
  const k=await crypto.subtle.importKey('raw',puzzleBytes(PUZZLE_KEY),'AES-GCM',false,['decrypt']);
  const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:puzzleBytes(PUZZLE_NONCE),additionalData:new TextEncoder().encode('game-puzzle-202512-v1')},k,puzzleBytes(PUZZLE_CIPHER));
  const titles=JSON.parse(new TextDecoder().decode(plain));
  puzzleSource=titles.map(title=>({title,appearances:['202512']}));
 })();
 return puzzleDataPromise;
}

let puzzleState=null, puzzleSize=5, puzzleYear='202512', puzzleDemo=false;
const minTitleLength=n=>({5:2,10:5,15:8,20:11,25:14})[n];
const puzzleNeighbors=(i,n)=>[i%n>0?i-1:-1,i%n<n-1?i+1:-1,i>=n?i-n:-1,i<n*(n-1)?i+n:-1].filter(x=>x>=0);
const puzzleSymbols=Array.from('!?.,:;()[]·~「」『』\'"-+&');
function puzzleTokens(title){return Array.from(title).filter(ch=>ch.trim()&&ch!==' ')}
function puzzleMatches(board,word,target){const n=Math.sqrt(board.length);const hits=[];for(let start=0;start<n*n;start++)for(const step of [1,n]){const ix=word.map((_,k)=>start+k*step);if(ix.at(-1)>=n*n||step===1&&Math.floor(start/n)!==Math.floor(ix.at(-1)/n))continue;if(target&&ix.some((v,k)=>v!==target[k]))continue;if(ix.every((v,k)=>board[v]?.kind==='title'&&board[v]?.char===word[k]))hits.push(ix)}return hits}
function puzzleWordPool(){return puzzleSource.filter(x=>x&&typeof x.title==='string'&&Array.isArray(x.appearances)&&x.appearances.some(t=>String(t).includes(puzzleYear))).filter(x=>{const len=puzzleTokens(x.title).length;return len>=minTitleLength(puzzleSize)&&len<=puzzleSize})}
function puzzlePick(){const pool=puzzleWordPool();return pool.length?pool[Math.floor(Math.random()*pool.length)].title:null}
function fillerChar(letters){const pool=letters.filter(ch=>/[가-힣]/.test(ch));const syll=pool.length?pool:['가','나','다'];return syll[Math.floor(Math.random()*syll.length)]}
function makePuzzle(word,level,n){
 const letters=puzzleTokens(word);
 if(letters.length>n)throw Error('글자판보다 제목이 깁니다');
 const vertical=Math.random()<.5;
 const row=vertical?Math.floor(Math.random()*(n-letters.length+1)):Math.floor(Math.random()*n);
 const col=vertical?Math.floor(Math.random()*n):Math.floor(Math.random()*(n-letters.length+1));
 const targets=letters.map((_,k)=>(row+(vertical?k:0))*n+col+(vertical?0:k));
 const board=Array.from({length:n*n},()=>({kind:'filler',char:''}));
 targets.forEach((i,k)=>{board[i]={kind:'title',char:letters[k]}});
 // 빈칸은 정답 줄/열의 바로 옆에서 시작합니다. 처음에 제목 블록을
 // 빈칸으로 한 번 반드시 이동시켜, 이용자가 즉시 복원할 수 있는 퍼즐만 만듭니다.
 const edges=targets.flatMap(i=>puzzleNeighbors(i,n).filter(j=>!targets.includes(j)).map(j=>({from:i,to:j})));
 const edge=edges[Math.floor(Math.random()*edges.length)];
 let empty=edge.to;
 board[empty]=null;
 const undo=[];
 const shuffleMove=(pos)=>{const old=empty;board[empty]=board[pos];board[pos]=null;undo.push(old);empty=pos};
 shuffleMove(edge.from);
 // 역이동 방지 + 짧은 이동 경로. 직전 정답 위치에서 지나치게 멀어지지 않습니다.
 const steps=n===5?12:n===10?20:n===15?26:n===20?32:38;
 for(let i=0;i<steps;i++){
  const back=undo[undo.length-1];
  const pool=puzzleNeighbors(empty,n).filter(j=>j!==back);
  if(!pool.length)break;
  // 필요 이상으로 정답 글자들을 흩뜨리지 않도록 빈칸은 정답 영역 근처에서 유지
  shuffleMove(pool[Math.floor(Math.random()*pool.length)]);
 }
 return {board,word:letters,title:word,targets,empty,level:2,n,moves:0,solved:false,undo,titleRevealed:false};
}
function showPuzzleUnavailable(){
 const empty=puzzleSource.length===0;
 base('슬라이딩 퍼즐',`<section class="panel"><div class="question-head"><strong>🧠 제목 슬라이딩 퍼즐</strong></div>${puzzleControls()}<p class="empty-state">${empty?'202512 출현 작품 데이터가 아직 연결되지 않았습니다.':'이 크기에 맞는 202512 출현 작품 제목이 없습니다.'}</p><div class="actions"><button class="outline" id="puzzle-demo">예시로 작동 테스트</button></div><div class="actions"><button class="outline" id="puzzle-import">JSON 불러오기</button><input hidden type="file" id="puzzle-file" accept=".json,application/json"></div><p class="help">202512 출현 이력 JSON을 연결하면 해당 작품에서 무작위로 출제됩니다. 예시 테스트는 실제 출현 작품을 뜻하지 않습니다.</p></section>${footer('puzzle')}`);
 bindPuzzleControls();document.getElementById('puzzle-demo').onclick=()=>{puzzleDemo=true;newPuzzle()};
 const file=document.getElementById('puzzle-file');document.getElementById('puzzle-import').onclick=()=>file.click();file.onchange=async()=>{try{const data=JSON.parse(await file.files[0].text());if(!Array.isArray(data)||!data.every(x=>typeof x.title==='string'&&Array.isArray(x.appearances)))throw Error('형식 오류');puzzleSource=data;puzzleDemo=false;newPuzzle()}catch(e){alert('제목과 appearances 배열을 가진 JSON 목록을 선택해 주세요.')}};bindRestart('puzzle',()=>{puzzleDemo=false;newPuzzle()});
}
function puzzleControls(){return `<div class="puzzle-toolbar"><label for="puzzle-size">블록 크기</label><select id="puzzle-size">${[5,10,15].map(n=>`<option value="${n}" ${n===puzzleSize?'selected':''}>${n}×${n}</option>`).join('')}</select></div>`}
function bindPuzzleControls(){const el=document.getElementById('puzzle-size');if(el)el.onchange=e=>{puzzleSize=+e.target.value;newPuzzle()}}
async function newPuzzle(){current='puzzle';puzzleYear='202512';if(!puzzleDemo){try{await ensurePuzzleData()}catch(err){console.error('게임 제목 복호화 실패',err);showPuzzleUnavailable();return}}let word=puzzleDemo?(['시맨틱 에러','유언 때문에 죽는 건 잠깐 미뤘습니다','충격! 머리가 모니터인 남자친구 실존'].find(t=>{let z=puzzleTokens(t).length;return z>=minTitleLength(puzzleSize)&&z<=puzzleSize})||'전마'):puzzlePick();if(!word){puzzleState=null;showPuzzleUnavailable();return}puzzleState=makePuzzle(word,2,puzzleSize);renderPuzzle()}
function startMixPuzzle(word){const t=puzzleTokens(word);const size=[5,10,15].find(n=>t.length<=n);if(!size){mixState.index++;renderMix();return;}puzzleState=makePuzzle(word,2,size);renderPuzzle(true)}
function renderPuzzle(inMix=false){const s=puzzleState,n=s.n,level=s.level;const count=inMix?`${mixState.index+1} / ${mixState.questions.length}`:'';const header=inMix?'🎲 랜덤게임':'슬라이딩 퍼즐';base(header,`<section class="panel"><div class="question-head"><strong>🧠 제목 슬라이딩 퍼즐</strong>${inMix?`<span class="counter" id="move-counter">${count}</span>`:""}</div>${!inMix?puzzleControls():''}${!inMix&&puzzleDemo?'<p class="sample">※ 예시 제목으로 이동을 테스트하는 중입니다.</p>':''}<p class="puzzle-title" id="puzzle-title" aria-live="polite">${s.titleRevealed?`완성할 제목: <b>${esc(s.title)}</b>`:"제목을 맞혀보세요!"}</p><p class="help" style="text-align:center">빨간 테두리 칸에 작품 제목을 순서대로 놓으세요. 빈칸 옆의 블록을 누르면 자동으로 이동합니다.</p><div class="puzzle-grid" id="puzzle-grid" style="--puzzle-n:${n};--puzzle-gap:${n>=15?1: n>=10?2:4}px;--puzzle-font:${n===5?22:n===10?13:n===15?10:8}px;--puzzle-radius:${n>=15?2:6}px">${s.board.map((tile,i)=>`<button type="button" class="tile ${tile===null?'empty chosen':tile.kind==='filler'?'filler':''} ${tile!==null&&puzzleNeighbors(s.empty,n).includes(i)?'movable':''} ${!s.solved&&[2,4].includes(level)&&s.targets.includes(i)?'target':''}" data-tile="${i}" aria-label="${Math.floor(i/n)+1}행 ${i%n+1}열 ${tile===null?'빈칸':tile.char||'글자 없는 블록'}" ${s.solved?'disabled':''}>${tile?.char?esc(tile.char):''}</button>`).join('')}</div><p class="feedback" id="feedback" role="status" aria-live="polite"></p><div class="actions"><button class="outline" id="puzzle-reveal" type="button" ${s.titleRevealed?"disabled":""}>${s.titleRevealed?"제목 확인 완료":"제목 보기"}</button></div><div class="actions" id="puzzle-next" hidden><button class="primary next-btn" id="next-puzzle">${inMix?'다음 문제 →':'새로운 퍼즐 풀기'}</button></div></section>${footer(inMix?'mix':'puzzle')}`);puzzleChosen=true;puzzleAnimating=false;
app.querySelectorAll('[data-tile]').forEach(btn=>btn.onclick=()=>{
  if(puzzleAnimating||s.solved)return;
  const i=+btn.dataset.tile;
  if(i===s.empty){puzzleChosen=true;document.querySelector(`[data-tile="${i}"]`)?.classList.add('chosen');return}
  if(!puzzleNeighbors(s.empty,n).includes(i)){
    btn.classList.remove('invalid');void btn.offsetWidth;btn.classList.add('invalid');
    setTimeout(()=>btn.classList.remove('invalid'),270);return;
  }
  puzzleChosen=false;puzzleAnimating=true;
  const emptyIndex=s.empty;
  const from=btn.getBoundingClientRect();
  const to=document.querySelector(`[data-tile="${emptyIndex}"]`).getBoundingClientRect();
  btn.style.transform=`translate(${to.left-from.left}px,${to.top-from.top}px)`;
  const blank=document.querySelector(`[data-tile="${emptyIndex}"]`);
  if(blank)blank.style.transform=`translate(${from.left-to.left}px,${from.top-to.top}px)`;
  setTimeout(()=>{
    [s.board[i],s.board[emptyIndex]]=[s.board[emptyIndex],s.board[i]];s.empty=i;s.moves++;
    if(s.undo?.length&&i===s.undo.at(-1)){s.undo.pop()}else{s.undo=[]}
    const hits=puzzleMatches(s.board,s.word,[2,4].includes(level)?s.targets:null);
    if(hits.length){s.solved=true;recordCorrect(inMix?'mix':'puzzle',15);if(!inMix){updatePuzzleBest(n);recordClear('puzzle',25);}}
    for(const el of document.querySelectorAll('[data-tile]')){el.style.transition='none';el.style.transform='';}
    paintPuzzle(hits.length?hits[0]:null,inMix);
    for(const el of document.querySelectorAll('[data-tile]')){void el.offsetWidth;el.style.transition='';}
    puzzleAnimating=false;
    if(hits.length&&inMix){const snap=mixState;const questionIndex=snap.index;advanceAfterThreeSeconds(()=>{if(current==='mix'&&mixState===snap&&snap.index===questionIndex){snap.index++;renderMix()}})}
  },190);
});if(!inMix)bindPuzzleControls();document.getElementById('puzzle-reveal').onclick=()=>{s.titleRevealed=true;document.getElementById('puzzle-title').innerHTML='완성할 제목: <b>'+esc(s.title)+'</b>';const button=document.getElementById('puzzle-reveal');button.textContent='제목 확인 완료';button.disabled=true};document.getElementById('next-puzzle').onclick=()=>{if(inMix){mixState.index++;renderMix()}else newPuzzle()};bindRestart(inMix?'mix':'puzzle',inMix?newMix:newPuzzle)}
function paintPuzzle(hits,inMix){const s=puzzleState,n=s.n;const moveCounter=document.getElementById('move-counter');if(moveCounter&&inMix)moveCounter.textContent=`${mixState.index+1} / ${mixState.questions.length}`;document.querySelectorAll('[data-tile]').forEach((el,i)=>{const tile=s.board[i];el.textContent=tile?.char||'';el.className='tile'+(tile===null?' empty chosen':tile.kind==='filler'?' filler':'')+(!s.solved&&[2,4].includes(s.level)&&s.targets.includes(i)?' target':'')+(hits?.includes(i)?' solved':'')+(tile!==null&&!s.solved&&puzzleNeighbors(s.empty,n).includes(i)?' movable':'');el.disabled=s.solved;el.setAttribute('aria-label',`${Math.floor(i/n)+1}행 ${i%n+1}열 ${tile===null?'빈칸':tile.char||'글자 없는 블록'}`)});if(hits){document.getElementById('feedback').textContent='정답입니다!';document.getElementById('feedback').className='feedback good';document.getElementById('puzzle-next').hidden=false}}
// URL 경로에 의존하지 않는 완전한 단일 파일
intro();
